svg.script:
/*  */
(function() {
  // Data dictionary for Inspector Panel updates based on selected timeline node
  var inspectorData = {
    '1t': {
      badge: 'EXAME EM DESTAQUE',
      title: '1º TRIMESTRE (0–12w)',
      sub: 'Consultas Iniciais e Cadastro do Pré-Natal',
      bullets: [
        '• Tipagem Sanguínea (ABO) + Fator Rh',
        '• Coombs Indireto (se Rh negativo)',
        '• Hemograma completo (Hb/Ht baseline)',
        '• Glicemia de Jejum (Corte crucial: 92)',
        '• Sorologias: HIV, VDRL, HBsAg, Toxo',
        '• EAS + Urocultura c/ antibiograma',
        '• Eletroforese de Hemoglobina (Hb)'
      ],
      ruleTitle: 'REGRAS DE GLICEMIA DE JEJUM (1ºT):',
      ruleLines: [
        '< 92 mg/dL: Normal → TOTG 75g em 24–28w',
        '92 a 125 mg/dL: DM Gestacional (DMG)',
        '≥ 126 mg/dL: DM Pré-gestacional (Prévio)',
        '*Se DMG ou DM prévio no 1ºT, NÃO faz TOTG no 2ºT!'
      ],
      tipLines: [
        'A Lei 14.598/2023 garante 2 exames',
        'ultrassonográficos no 1º quadrimestre no',
        'SUS (prevenção e datação precoce).',
        'Fixe: 1ºT estabelece a linha de base!'
      ],
      color: 'var(--a16p6-teal)'
    },
    '24-28w': {
      badge: 'JANELA CRÍTICA DE RASTREIO',
      title: '24 – 28 SEMANAS (TOTG 75g)',
      sub: 'Rastreio de Diabetes Gestacional & Rh-',
      bullets: [
        '• TOTG 75g de glicose (Se Jejum 1ºT < 92)',
        '• Curva de 3 pontos: Jejum, 1 hora, 2 horas',
        '• Repetição do Coombs Indireto (se Rh-)',
        '• Imunoglobulina Anti-D com 28w (se Coombs-)',
        '• Avaliação de ganho ponderal e PA',
        '• Ecocardiograma Fetal (~24w por Lei)',
        '• Medida da altura uterina (AU)'
      ],
      ruleTitle: 'CRITÉRIOS DIAGNÓSTICOS DO TOTG 75g:',
      ruleLines: [
        'Jejum ≥ 92 mg/dL',
        '1 hora ≥ 180 mg/dL',
        '2 horas ≥ 153 mg/dL',
        '★ APENAS 1 VALOR ALTERADO = DIAGNÓSTICO DE DMG!'
      ],
      tipLines: [
        'Apenas gestantes com Jejum <92 mg/dL no 1ºT',
        'têm indicação de realizar o TOTG 75g.',
        'Não confunda: 1 valor alterado já confirma DMG!',
        'Se Rh- e Coombs (-), fazer Anti-D com 28 semanas.'
      ],
      color: 'var(--a16p6-coral)'
    },
    '3t-reza': {
      badge: 'EXAMES DE REPETIÇÃO (3ºT)',
      title: '3º TRIMESTRE (REZA)',
      sub: 'O que repete no 3º Trimestre (28–30w+)',
      bullets: [
        '• R: Rh (Coombs indireto mensal se Rh-)',
        '• E: Exames Sorológicos (HIV, VDRL, HBsAg)',
        '• Z: Zika vírus (se sintomática/risco)',
        '• A: Anemia (Hemograma Hb/Ht)',
        '• A: Análise Urinária (EAS + Urocultura)',
        '• Toxoplasmose IgM/IgG (se suscetível/IgG-)',
        '• Rastreio de Bacteriúria Assintomática'
      ],
      ruleTitle: 'PEGADINHA RECORRENTE DA PROVA:',
      ruleLines: [
        'NÃO se repete a 1ª rotina inteira no 3ºT!',
        'NÃO repete: Tipagem ABO/Rh (já definida)',
        'NÃO repete: Eletroforese de Hb (já definida)',
        'NÃO repete: Parasitológico de fezes / TOTG'
      ],
      tipLines: [
        'Mnemônico REZA: Rh, Exames sorológicos,',
        'Zika e Anemia/Urina.',
        'O aluno que marca repetição completa erra a',
        'questão. Grave: no 3ºT você só REZA!'
      ],
      color: 'var(--a16p6-green)'
    },
    '35-37w': {
      badge: 'RASTREIO BACTERIANO',
      title: '35 – 37 SEMANAS (SWAB GBS)',
      sub: 'Streptococcus agalactiae (Grupo B)',
      bullets: [
        '• Swab Vaginoperineal (sem especulo!)',
        '• Validade da cultura: 5 semanas',
        '• Se GBS (+): Indicação de Profilaxia Intraparto',
        '• Antibiótico de escolha: Penicilina G EV',
        '• Alternativa: Ampicilina 2g EV inicial',
        '• Coleta em terço inferior da vagina + períneo',
        '• Avaliação de estabilidade hemodinâmica'
      ],
      ruleTitle: 'DISPENSA DO SWAB (INDICAÇÃO DIRETA DE IAP):',
      ruleLines: [
        '1. Bacteriúria por GBS na gestação atual',
        '2. Filho anterior com infecção neonatal por GBS',
        'Nestes 2 casos, NÃO colhe swab: a profilaxia',
        'intraparto (IAP) já é OBRIGATÓRIA!'
      ],
      tipLines: [
        'A cultura de GBS vale por 5 semanas.',
        'Se o parto não ocorrer no período, reavaliar.',
        'Profilaxia é INTRAPARTO (no trabalho de parto),',
        'nunca tratada antecipadamente no pré-natal!'
      ],
      color: 'var(--a16p6-gold)'
    },
    'admissao': {
      badge: 'PROTOCOLO DE MATERNIDADE',
      title: 'ADMISSÃO NO PARTO',
      sub: 'Testes Rápidos e Rastreio de Admissão',
      bullets: [
        '• Teste Rápido para HIV (Resultado imediato)',
        '• Teste Rápido para Sífilis / VDRL',
        '• Verificação de cartão de pré-natal e GBS',
        '• Tipagem Sanguínea (se não documentada)',
        '• Avaliação de dinamicidade uterina e colo',
        '• Ausculta dos batimentos cardíacos fetais (BCF)',
        '• Checagem de sinais de alarme e mecônio'
      ],
      ruleTitle: 'MÍNIMO OBRIGATÓRIO (MS / FEBRASGO):',
      ruleLines: [
        'Testes Rápidos de HIV + SÍFILIS na admissão',
        'de TODAS as gestantes no trabalho de parto.',
        'Permite AZT EV se HIV+ desconhecido/sem CV',
        'e Penicilina imediata no recém-nascido se Sífilis.'
      ],
      tipLines: [
        'Mesmo com pré-natal completo, os testes de',
        'admissão para HIV e Sífilis são compulsórios.',
        'Proteção direta contra a transmissão vertical',
        'no momento da emergência obstétrica.'
      ],
      color: 'var(--a16p6-blue)'
    }
  };

  function updateInspector(nodeKey) {
    var data = inspectorData[nodeKey];
    if (!data) return;

    document.getElementById('a16p6-insp-badge').textContent = data.badge;
    document.getElementById('a16p6-insp-title').textContent = data.title;
    document.getElementById('a16p6-insp-sub').textContent = data.sub;

    // Update bullets
    for (var i = 1; i <= 7; i++) {
      var el = document.getElementById('a16p6-bullet-' + i);
      if (el) {
        el.textContent = data.bullets[i - 1] || '';
      }
    }

    // Update rule box
    document.getElementById('a16p6-rule-title').textContent = data.ruleTitle;
    document.getElementById('a16p6-rule-line1').textContent = data.ruleLines[0] || '';
    document.getElementById('a16p6-rule-line2').textContent = data.ruleLines[1] || '';
    document.getElementById('a16p6-rule-line3').textContent = data.ruleLines[2] || '';
    document.getElementById('a16p6-rule-line4').textContent = data.ruleLines[3] || '';

    // Update tip box
    document.getElementById('a16p6-tip-line1').textContent = data.tipLines[0] || '';
    document.getElementById('a16p6-tip-line2').textContent = data.tipLines[1] || '';
    document.getElementById('a16p6-tip-line3').textContent = data.tipLines[2] || '';
    document.getElementById('a16p6-tip-line4').textContent = data.tipLines[3] || '';
  }

  // Tab Switcher Handler
  var tabs = [
    { id: 'a16p6-tab-timeline', view: 'a16p6-view-timeline' },
    { id: 'a16p6-tab-reza', view: 'a16p6-view-reza' },
    { id: 'a16p6-tab-legal', view: 'a16p6-view-legal' }
  ];

  tabs.forEach(function(tab) {
    var tabEl = document.getElementById(tab.id);
    if (!tabEl) return;

    tabEl.addEventListener('click', function() {
      // Reset all tabs
      tabs.forEach(function(t) {
        var el = document.getElementById(t.id);
        if (el) el.classList.remove('is-active');
        var v = document.getElementById(t.view);
        if (v) v.classList.add('a16p6-hidden');
      });

      // Activate clicked tab & view
      tabEl.classList.add('is-active');
      var targetView = document.getElementById(tab.view);
      if (targetView) targetView.classList.remove('a16p6-hidden');

      // If switching to REZA tab, load REZA info into inspector
      if (tab.id === 'a16p6-tab-reza') {
        updateInspector('3t-reza');
      } else if (tab.id === 'a16p6-tab-legal') {
        updateInspector('1t');
      }
    });
  });

  // Node Click Handler
  var nodes = [
    { id: 'a16p6-node-1t', key: '1t' },
    { id: 'a16p6-node-2428w', key: '24-28w' },
    { id: 'a16p6-node-3treza', key: '3t-reza' },
    { id: 'a16p6-node-3537w', key: '35-37w' },
    { id: 'a16p6-node-admissao', key: 'admissao' }
  ];

  nodes.forEach(function(node) {
    var nodeEl = document.getElementById(node.id);
    if (!nodeEl) return;

    nodeEl.addEventListener('click', function() {
      nodes.forEach(function(n) {
        var el = document.getElementById(n.id);
        if (el) el.classList.remove('is-selected');
      });
      nodeEl.classList.add('is-selected');
      updateInspector(node.key);
    });
  });

  // Initial state load
  updateInspector('1t');
})();
/*  */
